function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 15) return 'nums needs 1 to 15 nodes.';
  const seen = new Set();
  for (let i = 0; i < nums.length; i++) {
    const x = nums[i];
    if (!Number.isInteger(x) || x < 110 || x > 489) return 'Each node is a three-digit number from 110 to 489.';
    if (i > 0 && nums[i - 1] >= x) return 'nums must be strictly increasing.';
    const d = Math.floor(x / 100), p = Math.floor(x / 10) % 10;
    if (p < 1 || p > 2 ** (d - 1)) return `Slot ${p} does not exist on level ${d}.`;
    if (seen.has(d * 10 + p)) return 'Two nodes share the same level and slot.';
    seen.add(d * 10 + p);
  }
  if (!seen.has(11)) return 'The root (level 1, slot 1) must be present.';
  for (const key of seen) {
    const d = Math.floor(key / 10), p = key % 10;
    if (d > 1 && !seen.has((d - 1) * 10 + Math.ceil(p / 2))) return 'Every node except the root needs its parent.';
  }
  return null;
}

