  const values = new Map();
  for (const num of nums) {
    const key = Math.floor(num / 10);
    values.set(key, num % 10);
  }
  let total = 0;

  const dfs = (key, running) => {
    const depth = Math.floor(key / 10);
    const position = key % 10;
    const sum = running + values.get(key);
    const leftKey = (depth + 1) * 10 + 2 * position - 1;
    const rightKey = leftKey + 1;
    const hasLeft = values.has(leftKey);
    const hasRight = values.has(rightKey);
    if (!hasLeft && !hasRight) {
      total += sum;
      return;
    }
    if (hasLeft) {
      dfs(leftKey, sum);
    }
    if (hasRight) {
      dfs(rightKey, sum);
    }
  };

  dfs(11, 0);
  return total;
}

