function pathSum(nums) {
  const level = x => Math.floor(x / 100);
  const slot = x => Math.floor(x / 10) % 10;
  let total = 0;
  for (const node of nums) {
    const isLeaf = !nums.some(other => level(other) === level(node) + 1 && Math.ceil(slot(other) / 2) === slot(node));
    if (!isLeaf) continue;
    // Climb from the leaf to the root, adding every value on the way.
    let d = level(node), p = slot(node);
    while (d >= 1) {
      const current = nums.find(x => level(x) === d && slot(x) === p);
      total += current % 10;
      d -= 1;
      p = Math.ceil(p / 2);
    }
  }
  return total;
}

