function generate(rand, size) {
  const chance = size === 'large' ? 0.9 : 0.25 + rand() * 0.6;
  const maxDepth = size === 'large' ? 4 : 1 + Math.floor(rand() * 4);
  const nums = [];
  let slots = [1];
  for (let depth = 1; depth <= maxDepth && slots.length; depth++) {
    const next = [];
    for (const p of slots) {
      nums.push(depth * 100 + p * 10 + Math.floor(rand() * 10));
      if (depth < maxDepth) {
        if (rand() < chance) next.push(2 * p - 1);
        if (rand() < chance) next.push(2 * p);
      }
    }
    slots = next;
  }
  return [nums];
}
